        return float("inf"), None

    def bidirectional_search(start, goal):
        # Initialize the queues for BFS
        start_queue, goal_queue = [start], [goal]
        start_visited, goal_visited = {start}, {goal}
        distance = {start: 0, goal: 0}
        parent = {start: None, goal: None}

        while start_queue and goal_queue:
            # Breadth-First Search: explore the nearest node first
            if len(start_queue) > len(goal_queue):
                next_queue, next_visited, next_distance, next_parent = goal_queue, goal_visited, goal_visited, goal_visited
                next_queue, next_visited, next_distance, next_parent = goal_queue, goal_visited, goal_visited, goal_visited
                start_queue, start_visited, distance, parent = goal_queue, goal_visited, goal_visited, goal_visited
                goal_queue, goal_visited, distance, parent = start_queue, start_visited, distance, parent
            node = start_queue.pop(0)
            node_visited = start_visited.pop(0)
            node_distance = distance.pop(node)
            node_parent = parent.pop(node)
            for neighbor, weight in graph[node]:
                if neighbor not in node_visited:
                    node_queue = start_queue[:]
                    node_visited = start_visited[:]
                    node_visited.add(neighbor)
                    node_distance += weight
                    node_parent[neighbor] = node
                    node_queue.append(neighbor)
                    distance[neighbor] = node_distance
                    parent[neighbor] = node
                    if neighbor not in goal_visited:
                        start_queue = node_queue
                        start_visited = node_visited
                        distance = node_distance
                        parent = node_parent
                        break

        while node_parent[goal] != start:
            path = [goal] + [node_parent[goal)] for goal in path]
            goal = node_parent[goal]
        return distance[goal], path + [start]

    # Check for unreachable case
    if source == target:
        return 0, [source]

    # Perform bidirectional search
